<?php
declare(strict_types=1);
const REFUND_LABELS=['planned'=>'返金予定（未送金）','recorded'=>'返金記録済み','cancelled'=>'予定取消済み'];
function participantLifecycleView(array $p):string{
 $html='';$within=date('Y-m-d')<=setting()['change'];
 if($p['status']==='cancel_requested')$html='<h3>欠席申請を取り消す場合</h3><p>幹事の確認前なら、同じ申込番号のまま参加予定へ戻せます。定員と内容変更期限を確認します。</p>'.($within?form('withdraw_cancel',hidden('revision',$p['revision']).reasons().button('欠席申請を取り消して出席に戻す')):'<p>内容変更期限を過ぎています。幹事へご相談ください。</p>');
 if($p['status']==='cancelled')$html='<h3>もう一度参加を希望する場合</h3><p>幹事が定員・返金状況を確認して承認します。新規申込は不要です。</p>'.($within?form('request_rejoin',hidden('revision',$p['revision']).reasons().button('再参加を希望する')):'<p>内容変更期限を過ぎています。幹事へご相談ください。</p>');
 if($p['status']==='rejoin_requested')$html='<p>再参加の希望を受け付けました。幹事の承認をお待ちください。同じ申込番号・入金履歴を引き継ぎます。</p>';
 $rows=[];foreach(all("SELECT * FROM refunds WHERE registration_id=? AND status<>'cancelled' ORDER BY id",[$p['id']]) as $x)$rows[]=[yen((int)$x['amount']),h(REFUND_LABELS[$x['status']]).($x['status']==='recorded'?(paidRefund((int)$x['id'])===(int)$x['amount']?'（銀行照合済み）':'（銀行照合待ち）'):''),h($x['refund_date']?:'未定')];
 if($rows)$html.='<h3>返金の状況</h3><p>入金確認合計 '.yen(paidRegistration((int)$p['id'])).' ／ 返金記録合計 '.yen(refundedRegistration((int)$p['id'])).'</p>'.tabler(['返金額','状態','返金日'],$rows);
 return $html?'<section class="application-schedule" aria-label="欠席・再参加・返金のお手続き">'.$html.'</section>':'';
}
function refundOperationForm(string $action,int $id,string $content,string $label):string{return form($action,hidden('id',$id).$content.reasons().button($label));}
function refundManagementView():string{
 auth(true);$rows=[];foreach(all("SELECT r.*,u.name FROM registrations r JOIN users u ON u.id=r.user_id WHERE r.status IN ('cancel_requested','rejoin_requested') ORDER BY r.id") as $p){$rejoin=$p['status']==='rejoin_requested';$rows[]=[h(registrationNumber((int)$p['id']).' '.$p['name']),$rejoin?'再参加申請中':'欠席申請中',form($rejoin?'rejoin_decide':'cancel_decide',hidden('id',$p['id']).'<label class="field">判断<select name="decision"><option value="approve">'.($rejoin?'再参加を承認':'欠席・取消を承認').'</option><option value="reject">'.($rejoin?'今回は再参加を認めない':'参加予定に戻す').'</option></select></label>'.reasons().button('理由を付けて判断'))];}
 $html='<h1>欠席・再参加・返金</h1><section class="panel"><h2>申請を確認する</h2><p>返金額は幹事が確認して入力します。キャンセル料は自動計算しません。銀行への送金は別途行い、この画面は予定・実施内容・照合を記録します。</p>'.tabler(['申込','状態','判断'],$rows).'</section>';
 $options='';foreach(all('SELECT r.*,u.name FROM registrations r JOIN users u ON u.id=r.user_id ORDER BY r.id') as $p){if(!in_array($p['status'],['active','cancelled'],true))continue;$amount=availableRegistrationRefund((int)$p['id']);if($amount<=0)continue;$options.='<option value="'.$p['id'].'"'.((int)($_GET['registration_id']??0)===(int)$p['id']?' selected':'').'>'.h(registrationNumber((int)$p['id']).' '.$p['name'].' ／ 登録可能 '.yen($amount)).'</option>';}
 $html.='<section class="panel"><h2>返金予定を登録する</h2><p>取消確定または過払いの入金から、既存の予定・記録を引いた金額が上限です。</p>'.($options?form('refund_plan',hidden('request_key',bin2hex(random_bytes(16))).'<label class="field">返金する申込<select name="registration_id" required>'.$options.'</select></label>'.input('amount','返金予定額（円）','','number').reasons().button('返金予定を登録')):'<p>新しく返金予定を登録できる申込はありません。</p>').'<p><a class="btn btn-outline" href="?page=export&amp;kind=refunds">返金一覧CSV</a></p></section>';
 foreach(all('SELECT f.*,u.name FROM refunds f JOIN registrations r ON r.id=f.registration_id JOIN users u ON u.id=r.user_id ORDER BY f.id DESC') as $x){$id=(int)$x['id'];$matched=paidRefund($id);$html.='<section class="panel"><h3>返金 #'.$id.' ／ '.h(registrationNumber((int)$x['registration_id']).' '.$x['name']).' ／ '.yen((int)$x['amount']).'</h3><p>'.h(REFUND_LABELS[$x['status']]).' ／ 銀行照合 '.yen($matched).' ／ 返金日 '.h($x['refund_date']?:'未定').'</p><p>'.h($x['reference_text']).'</p>';
  if($x['status']==='planned')$html.=refundOperationForm('refund_record',$id,input('date','銀行で返金した日',date('Y-m-d'),'date').input('reference','送金確認番号・確認メモ（口座番号は不要）'),'送金済みの内容を記録（送金操作ではありません）').refundOperationForm('refund_cancel',$id,'','未送金の予定を取り消す');
  if($x['status']==='recorded'){$debits='';foreach(all("SELECT * FROM bank_transactions WHERE state='confirmed' AND debit>0 ORDER BY id DESC") as $t){$unused=(int)$t['debit']-usedBank((int)$t['id']);if($unused>0)$debits.='<option value="'.$t['id'].'">'.h('#'.$t['id'].' '.$t['txn_date'].' '.yen($unused).' '.$t['memo']).'</option>';}
   if($matched<(int)$x['amount'])$html.=$debits?refundOperationForm('refund_link',$id,'<label class="field">確認済み銀行出金<select name="bank_id" required>'.$debits.'</select></label>'.input('amount','照合金額（円）',(int)$x['amount']-$matched,'number'),'銀行出金と照合する'):'<p>銀行CSVで出金を取り込み、確認済みにしてください。</p>';
   if($matched===0)$html.=refundOperationForm('refund_undo',$id,'<p>誤記の訂正専用です。実際の送金は取り消されません。</p>','誤った返金記録を予定へ戻す');
  }$html.='</section>';
 }
 $rows=[];foreach(all('SELECT * FROM refund_links ORDER BY id DESC') as $a)$rows[]=['#'.$a['refund_id'],'#'.$a['bank_id'],yen((int)$a['amount']),(int)$a['active']?'有効':'取消済',(int)$a['active']?refundOperationForm('refund_unlink',(int)$a['id'],'','照合を取り消す'):''];return $html.'<section class="panel"><h2>返金と銀行出金の照合履歴</h2>'.tabler(['返金','出金明細','金額','状態','訂正'],$rows).'</section>';
}
function exportRecords(string $kind):array{return match($kind){'refunds'=>all('SELECT f.*,u.name FROM refunds f JOIN registrations r ON r.id=f.registration_id JOIN users u ON u.id=r.user_id ORDER BY f.id'),'cashbook'=>all('SELECT * FROM bank_transactions ORDER BY txn_date,id'),'finance'=>all('SELECT e.*,u.name FROM expenses e JOIN users u ON u.id=e.user_id ORDER BY e.id'),'logs'=>all('SELECT * FROM audit_logs ORDER BY id'),default=>all('SELECT r.*,u.name,u.email FROM registrations r JOIN users u ON u.id=r.user_id ORDER BY r.id')};}
